import{_ as i,C as a,o as r,c as l,j as t,a as o,E as n,ak as h}from"./chunks/framework.sV-XtlWr.js";const w=JSON.parse(`{"title":"Agent skills","description":"Seven SKILL.md files, installed by the reporter's CLI, that teach a coding agent what to do with Piwi's evidence: investigate a failure, heal a locator, fix a flaky test, write the missing one.","frontmatter":{"title":"Agent skills","description":"Seven SKILL.md files, installed by the reporter's CLI, that teach a coding agent what to do with Piwi's evidence: investigate a failure, heal a locator, fix a flaky test, write the missing one.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/agent-skills.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/agent-skills.html"}],["meta",{"property":"og:title","content":"Agent skills | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Seven SKILL.md files, installed by the reporter's CLI, that teach a coding agent what to do with Piwi's evidence: investigate a failure, heal a locator, fix a flaky test, write the missing one."}]]},"headers":[],"relativePath":"features/agent-skills.md","filePath":"features/agent-skills.md","lastUpdated":1790871667000}`),d={name:"features/agent-skills.md"};function c(p,e,k,g,f,u){const s=a("Needs");return r(),l("div",null,[e[0]||(e[0]=t("h1",{id:"agent-skills",tabindex:"-1"},[o("Agent skills "),t("a",{class:"header-anchor",href:"#agent-skills","aria-label":'Permalink to "Agent skills"'},"​")],-1)),n(s,{reporter:""}),e[1]||(e[1]=h(`<p>The <a href="/features/mcp.html">MCP server</a> gives an agent read access to your results; <strong>skills</strong> tell it what to <em>do</em> with them. A skill is a single <code>SKILL.md</code> file, the portable open format (front matter plus Markdown instructions) that Claude Code and other coding agents read from a project&#39;s skills directory. Piwi ships seven, and the reporter&#39;s CLI installs them into your test project.</p><h2 id="what-each-skill-does" tabindex="-1">What each skill does <a class="header-anchor" href="#what-each-skill-does" aria-label="Permalink to &quot;What each skill does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>What it does</th></tr></thead><tbody><tr><td><code>setup-piwi</code></td><td>Wire a Playwright project up to a dashboard: the same work <code>npx @piwitests/reporter init</code> does, driven by an agent.</td></tr><tr><td><code>investigate-failure</code></td><td>Investigate a failed run and propose a fix grounded in Piwi&#39;s evidence: error, steps, console, network, and the diff since the last green run.</td></tr><tr><td><code>apply-locator-healing</code></td><td>Replace a brittle locator with Piwi&#39;s ranked <a href="/features/locator-healing.html">healed locator</a> at its call site, then re-run to confirm.</td></tr><tr><td><code>stabilize-flaky-tests</code></td><td>Reproduce the highest-impact <a href="/features/flaky-tests.html">flaky tests</a> with the <a href="/features/flake-lab.html">Flake Lab</a>, fix what the reproducing condition points at (never by adding retries), then prove it with <code>piwi flake verify</code>.</td></tr><tr><td><code>run-the-right-tests</code></td><td>After a UI change, fix the locators it breaks with <a href="/features/preflight.html">preflight</a>; then pick and run the right <a href="/features/test-selection.html">selection</a> for the task (smoke, recently broken, a time budget) instead of the whole suite.</td></tr><tr><td><code>write-the-missing-test</code></td><td>Take the top <a href="/features/scenario-gaps.html">scenario gap</a> in scope, draft it from the graph, finish the assertion and add it in the same change.</td></tr><tr><td><code>fix-a-reported-bug</code></td><td>Take a <a href="/features/bug-reports.html">bug report</a>, write its failing test with <code>piwi bug &lt;id&gt; --write</code>, reproduce, fix, then remove <code>test.fail()</code> and run the spec and the tests that visit the page.</td></tr></tbody></table><p>Each skill prefers a connected Piwi <a href="/reference/mcp-tools.html">MCP tool</a> and falls back to the dashboard UI when MCP is not connected, so a skill works before the MCP server is set up, only more slowly.</p><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><p>The skills ship inside the reporter package. <code>npx @piwitests/reporter init</code> installs the six workflow skills as part of setup (everything but <code>setup-piwi</code>, which an agent runs before the reporter exists). The <strong>MCP server</strong> page of the dashboard (<code>/mcp</code>) lists them next to the tools.</p><h2 id="use-it" tabindex="-1">Use it <a class="header-anchor" href="#use-it" aria-label="Permalink to &quot;Use it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # install all seven into .claude/skills/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # see what each one does</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> investigate-failure</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .cursor/skills</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # one skill, elsewhere</span></span></code></pre></div><p>Invoke the CLI through the package name so npx resolves this package; a plain <code>npx piwi …</code> works once the reporter is a project dependency. <code>init</code> takes <code>--skills &lt;list&gt;</code> (or <code>all</code>, <code>none</code>), <code>--skills-dir</code> and <code>--no-skills</code> to change what setup installs. The <a href="/reference/cli.html#skills">CLI reference</a> lists every flag.</p><p>The skills are agent-agnostic Markdown: only the destination is tool-specific, so <code>--dir</code> points the install wherever your agent reads skills from. An existing file is left alone unless you pass <code>--force</code>, so a skill you edited stays yours.</p><p>Once installed, ask in plain words: &quot;why did the last CI run fail&quot;, &quot;fix the flaky checkout test&quot;, &quot;write the test we&#39;re missing for this change&quot;. The agent picks the skill whose description matches.</p><h2 id="prompts-the-no-install-alternative" tabindex="-1">Prompts, the no-install alternative <a class="header-anchor" href="#prompts-the-no-install-alternative" aria-label="Permalink to &quot;Prompts, the no-install alternative&quot;">​</a></h2><p>The MCP server also offers a <code>setup_piwi</code> <strong>prompt</strong>, which a client shows as a slash command with nothing to install. It knows this instance&#39;s URL, whether it requires an API key and its existing projects, which a static skill cannot. The prompt needs MCP; the <code>setup-piwi</code> skill works offline. See <a href="/features/mcp.html#prompts">MCP server</a>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Instructions, not code.</strong> A skill tells an agent which evidence to read and in which order; the agent still writes the fix, and you review it.</li><li><strong>Updated with the reporter.</strong> A newer reporter ships newer skills; run <code>skills add --force</code> to replace the installed copies, which overwrites any edits.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/mcp.html">MCP server</a>: the tools the skills call</li><li><a href="/reference/mcp-tools.html">MCP tools</a>: every tool, by module</li><li><a href="/reference/cli.html#skills">Piwi CLI: skills</a>: every flag of <code>skills</code> and <code>init</code></li></ul>`,17))])}const y=i(d,[["render",c]]);export{w as __pageData,y as default};
